int CountPairs(int[] values)
{
    var count = 0;
    for (var i = 0; i < values.Length; i++)
    {
        for (var j = i + 1; j < values.Length; j++)
        {
            if (values[i] == values[j])
                count++;
        }
    }
    return count;
}
